head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getPopupUrl]<br/>현재 팝업 화면의 WebSquare 페이지 URL 을 반환합니다.",
    "validation" : [
        "현재 팝업 화면의 URL 을 반환해야 합니다.",
        "팝업 화면이 wframePopup 으로 실행된 경우만 동작해야 합니다.",
        "팝업 내부에서만 호출하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var options = {
        id: "getPopupUrl_popup",
        type: "wframePopup",
        width: "600px",
        height: "250px",
        top: "100px",
        left: "100px",
        popupName: "getPopupUrl 테스트",
        modal: false
    };

    $p.openPopup("/sample/common_link/p_getPopupUrl_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (wframePopup)");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 getPopupUrl() 결과를 확인하세요.");
}
